def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    steady_bids = []
    spike_bids = []
    opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) <= 85:
                    steady_bids.append(float(bid))
                else:
                    spike_bids.append(float(bid))

    if opp_count == 0:
        return max(0.0, min(float(budget), 15.0))

    units = supply / WATER_REQ
    scarcity = units < 2.0
    medium_tight = units < 2.5

    max_prev = max(prev_bids) if prev_bids else 0.0
    steady_anchor = max(steady_bids) if steady_bids else 72.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water >= 2:
        danger += 2
    elif no_water >= 1:
        danger += 1
    if scarcity:
        danger += 2
    elif medium_tight:
        danger += 1
    if day >= 8:
        danger += 1

    if danger >= 4:
        target = max(78.0, steady_anchor + 3.0)
        if spike_bids:
            target = max(target, min(max_prev + 1.0, 110.0))
    elif danger >= 2:
        target = max(58.0, steady_anchor - 2.0)
        if scarcity:
            target = max(target, steady_anchor + 1.5)
    else:
        if not scarcity and supply >= 24:
            target = 18.0
        elif not medium_tight:
            target = 32.0
        else:
            target = 45.0

    if budget < target:
        if danger >= 3:
            target = budget
        else:
            target = min(budget, max(0.0, budget * 0.55))

    if budget <= 0:
        return 0.0

    return max(0.0, min(float(budget), float(target)))
